import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class UserLookup {
    public static void main(String[] args) throws Exception {
        // Assume the username comes from an HTTP request parameter
        String username = args[0];   // e.g., "?username=admin"

        // *** GOOD: use a prepared statement with a parameter placeholder ***
        String query = "SELECT * FROM users WHERE username = ?";

        try (Connection conn = DriverManager.getConnection(
                 "jdbc:mysql://localhost:3306/appdb", "appuser", "apppass");
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            // Bind the user‑supplied value safely
            pstmt.setString(1, username);

            ResultSet rs = pstmt.executeQuery();
            while (rs.next()) {
                System.out.println("User: " + rs.getString("username"));
            }
        }
    }
}
